use palette::{Srgb, Lab, Lch, Oklab, Oklch, Hsl, Hsv, IntoColor};
fn main() {
    for hex in ["#ff0000","#ff8000","#123456","#00ff00","#808080","#7f7f7f"] {
        let c = csscolorparser::parse(hex).unwrap();
        let rgba = c.to_rgba8();
        let srgb = Srgb::new(rgba[0] as f32 /255.0, rgba[1] as f32/255.0, rgba[2] as f32/255.0);
        let lab: Lab = srgb.into_color();
        let lch: Lch = srgb.into_color();
        let hsl: Hsl = srgb.into_color();
        let hsv: Hsv = srgb.into_color();
        let oklab: Oklab = srgb.into_color();
        let oklch: Oklch = srgb.into_color();
        // luminance approx as in pastel: see https://www.w3.org/TR/2008/REC-WCAG20-20081211/#relativeluminancedef
        // pastel outputs for red luminance 0.213, brightness 0.299 . Let's compute usual formulas.
        // brightness approx = (299*r + 587*g + 114*b)/1000 normalized? Let's compute.
        let r = rgba[0] as f32 /255.0;
        let g = rgba[1] as f32 /255.0;
        let b = rgba[2] as f32 /255.0;
        // relative luminance? Using linearized?
        fn srgb_to_linear(c: f32) -> f32 { if c <= 0.04045 { c/12.92 } else { ((c+0.055)/1.055).powf(2.4) } }
        let rl = srgb_to_linear(r);
        let gl = srgb_to_linear(g);
        let bl = srgb_to_linear(b);
        let lum = 0.2126*rl + 0.7152*gl + 0.0722*bl;
        let bright = (0.299*r + 0.587*g + 0.114*b);
        println!("hex {} lab {:?} lch chroma {} hue {} hsl h {} s {} l {} hsv v {} oklab {:?} oklch {:?} lum {:.3} bright {:.3}", hex, lab, lch.chroma, lch.hue.into_inner(), hsl.hue.into_inner(), hsl.saturation, hsl.lightness, hsv.value, oklab, oklch, lum, bright);
    }
}
