{"command":"python3 <<'PY'
# Let's attempt to replicate Lab distance mapping for 8-bit
# Implement rgb -> Lab conversion approximating sRGB D65 as in palette
import math

def srgb_to_linear(c):
    c = c/255.0
    if c <= 0.04045:
        return c/12.92
    else:
        return ((c+0.055)/1.055)**2.4

def rgb_to_xyz(r,g,b):
    rl = srgb_to_linear(r)
    gl = srgb_to_linear(g)
    bl = srgb_to_linear(b)
    # matrix from sRGB to XYZ (D65) as per palette
    x = 0.4124564*rl + 0.3575761*gl + 0.1804375*bl
    y = 0.2126729*rl + 0.7151522*gl + 0.0721750*bl
    z = 0.0193339*rl + 0.1191920*gl + 0.9503041*bl
    return (x,y,z)

def xyz_to_lab(x,y,z):
    # reference white D65
    xn, yn, zn = 0.95047, 1.0, 1.08883
    x/=xn; y/=yn; z/=zn
    def f(t):
        delta = 6.0/29.0
        if t > delta**3:
            return t**(1/3)
        else:
            return t/(3*delta**2) + 4/29
    fx = f(x); fy = f(y); fz = f(z)
    L = 116*fy -16
    a = 500*(fx - fy)
    b = 200*(fy - fz)
    return (L,a,b)

def rgb_to_lab(r,g,b):
    return xyz_to_lab(*rgb_to_xyz(r,g,b))

def palette256_rgb(idx):
    if idx <16:
        vals = [(0,0,0),(128,0,0),(0,128,0),(128,128,0),(0,0,128),(128,0,128),(0,128,128),(192,192,192),(128,128,128),(255,0,0),(0,255,0),(255,255,0),(0,0,255),(255,0,255),(0,255,255),(255,255,255)]
        return vals[idx]
    elif idx <232:
        c=idx-16
        r=c//36; g=(c%36)//6; b=c%6
        levels=[0,95,135,175,215,255]
        return (levels[r], levels[g], levels[b])
    else:
        v=8+(idx-232)*10
        return (v,v,v)

def nearest_lab(r,g,b):
    target= rgb_to_lab(r,g,b)
    best=None; bestd=float('inf')
    for i in range(256):
        pr,pg,pb=palette256_rgb(i)
        lab= rgb_to_lab(pr,pg,pb)
        d = (target[0]-lab[0])**2 + (target[1]-lab[1])**2 + (target[2]-lab[2])**2
        if d<bestd:
            bestd=d; best=i
    return best

def nearest_rgb_euclid(r,g,b):
    best=None; bestd=float('inf')
    for i in range(256):
        pr,pg,pb=palette256_rgb(i)
        d=(r-pr)**2+(g-pg)**2+(b-pb)**2
        if d<bestd:
            bestd=d; best=i
    return best

# test cases we observed
import subprocess as sp
def pastel_ansi(val):
    r=sp.run(["./executable","--color-mode","off","format","ansi-8bit-value",val], stdout=sp.PIPE, stderr=sp.PIPE)
    return int(r.stdout.decode().strip())

cases = ["#ff0000","#ff8000","#123456","#00ff00","gray(0.5)","#c5d714","#6f4790","#473080","#4b9e32","#33b5de"]
for hexcol in cases:
    # parse hex to rgb
    if hexcol.startswith("#"):
        h=hexcol[1:]
        if len(h)==6:
            r=int(h[0:2],16); g=int(h[2:4],16); b=int(h[4:6],16)
        elif len(h)==3:
            r=int(h[0]*2,16); g=int(h[1]*2,16); b=int(h[2]*2,16)
        else:
            continue
    elif hexcol.startswith("gray"):
        # gray(0.5) => 128
        r=g=b=128
    else:
        continue
    lab_best=nearest_lab(r,g,b)
    rgb_best=nearest_rgb_euclid(r,g,b)
    pastel=pastel_ansi(hexcol)
    print(f"{hexcol} rgb {r,g,b} lab_best {lab_best} {palette256_rgb(lab_best)} rgb_best {rgb_best} {palette256_rgb(rgb_best)} pastel {pastel} {palette256_rgb(pastel)} match_lab {lab_best==pastel} match_rgb {rgb_best==pastel}")

# more random mismatches earlier
import random
random.seed(0)
for _ in range(10):
    r=random.randint(0,255); g=random.randint(0,255); b=random.randint(0,255)
    hexcol=f"#{r:02x}{g:02x}{b:02x}"
    lab_best=nearest_lab(r,g,b)
    rgb_best=nearest_rgb_euclid(r,g,b)
    pastel=pastel_ansi(hexcol)
    print(f"{hexcol} lab {lab_best} rgb {rgb_best} pastel {pastel} lab_match {lab_best==pastel} rgb_match {rgb_best==pastel}")

