#[derive(Clone, Copy, Debug)]
struct Color { r: u8, g: u8, b: u8, alpha: f32 }
impl Color {
    fn new(r: u8, g: u8, b: u8, alpha: f32) -> Self { Color{ r,g,b, alpha } }
    fn from_css(c: csscolorparser::Color) -> Self { let rgba=c.to_rgba8(); Color::new(rgba[0], rgba[1], rgba[2], rgba[3] as f32/255.0) }
    fn to_srgb(&self) -> Srgb { Srgb::new(self.r as f32/255.0, self.g as f32/255.0, self.b as f32/255.0) }
    fn from_srgb(srgb: Srgb, alpha: f32) -> Self { let s=srgb.clamp(); Color::new((s.red*255.0).round() as u8, (s.green*255.0).round() as u8, (s.blue*255.0).round() as u8, alpha) }
