            format!("#{:02x}{:02x}{:02x}{:02x}", self.r, self.g, self.b, (self.alpha*255.0).round() as u8)
        } else { format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b) }
    }
}

fn parse_color(s: &str) -> Option<Color> {
    let t = s.trim();
    if t.is_empty() { return None; }
    if t.to_lowercase()=="transparent" { return None; }
    // gray
    if t.starts_with("gray(") && t.ends_with(')') {
        let inner = &t[5..t.len()-1].trim();
        let v = if inner.ends_with('%') {
            let num = inner.trim_end_matches('%').trim().parse::<f64>().ok()?;
            (num/100.0).clamp(0.0,1.0)
        } else {
            let num = inner.parse::<f64>().ok()?;
            if num > 1.0 { 1.0 } else { num.clamp(0.0,1.0) }
        };
        let byte = (v*255.0).round() as u8;
        return Some(Color::new(byte,byte,byte,1.0));
    }
    // check function name case sensitivity
    if let Some(open) = t.find('(') {
        if let Some(_) = t.rfind(')') {
            let fname = t[..open].trim();
            if fname.chars().any(|c| c.is_alphabetic()) && fname != fname.to_lowercase() {
                return None;
            }
        }
    }
    // palette lab/lch/oklab/oklch direct handling
    let try_palette = || -> Option<Color> {
        let open = t.find('(')?;
        let close = t.rfind(')')?;
        let fname = t[..open].trim();
        if fname != fname.to_lowercase() { return None; }
        let inner = t[open+1..close].trim();
        let normalized = inner.replace(',', " ");
        let parts: Vec<&str> = normalized.split_whitespace().filter(|s| !s.is_empty()).collect();
        match fname {
            "lab" => {
                if parts.len()!=3 { return None; }
                let l: f32 = parts[0].parse().ok()?;
                let a: f32 = parts[1].parse().ok()?;
                let b: f32 = parts[2].parse().ok()?;
                let lab = PalLab::new(l, a, b);
                let srgb: Srgb = lab.into_color();
                let srgb = srgb.clamp();
                return Some(Color::new((srgb.red*255.0).round() as u8, (srgb.green*255.0).round() as u8, (srgb.blue*255.0).round() as u8, 1.0));
            },
            "lch" => {
                if parts.len()!=3 { return None; }
                let l: f32 = parts[0].parse().ok()?;
                let c: f32 = parts[1].parse().ok()?;
                let h: f32 = parts[2].parse().ok()?;
                let lch = PalLch::new(l, c, h);
                let srgb: Srgb = lch.into_color();
                let srgb = srgb.clamp();
                return Some(Color::new((srgb.red*255.0).round() as u8, (srgb.green*255.0).round() as u8, (srgb.blue*255.0).round() as u8, 1.0));
            },
            "oklab" => {
                if parts.len()!=3 { return None; }
                let l: f32 = parts[0].parse().ok()?;
                let a: f32 = parts[1].parse().ok()?;
                let b: f32 = parts[2].parse().ok()?;
                let oklab = PalOklab::new(l, a, b);
                let srgb: Srgb = oklab.into_color();
                let srgb = srgb.clamp();
                return Some(Color::new((srgb.red*255.0).round() as u8, (srgb.green*255.0).round() as u8, (srgb.blue*255.0).round() as u8, 1.0));
            },
            "oklch" => {
                if parts.len()!=3 { return None; }
                let l: f32 = parts[0].parse().ok()?;
                let c: f32 = parts[1].parse().ok()?;
                let h: f32 = parts[2].parse().ok()?;
                let oklch = PalOklch::new(l, c, h);
                let srgb: Srgb = oklch.into_color();
                let srgb = srgb.clamp();
                return Some(Color::new((srgb.red*255.0).round() as u8, (srgb.green*255.0).round() as u8, (srgb.blue*255.0).round() as u8, 1.0));
            },
            _ => None,
        }
    };
    if let Some(c) = try_palette() { return Some(c); }
    // comma triple without function
    let has_alpha = t.chars().any(|ch| ch.is_ascii_alphabetic());
    if !has_alpha {
        let normalized = t.replace(',', " ");
        let parts: Vec<&str> = normalized.split_whitespace().collect();
        if parts.len()==3 {
            let mut nums=Vec::new();
            let mut ok=true;
            for p in &parts {
                if p.ends_with('%') { ok=false; break; }
                if let Ok(v)=p.parse::<f64>() { nums.push(v); } else { ok=false; break; }
            }
            if ok {
                let r=nums[0].round().clamp(0.0,255.0) as u8;
                let g=nums[1].round().clamp(0.0,255.0) as u8;
                let b=nums[2].round().clamp(0.0,255.0) as u8;
                return Some(Color::new(r,g,b,1.0));
            }
        }
    }
    if !t.starts_with('#') && t.chars().all(|c| c.is_ascii_hexdigit()) && (t.len()==3||t.len()==4||t.len()==6||t.len()==8) {
        if let Ok(c)=csscolorparser::parse(&format!("#{}", t)) { return Some(Color::from_css(c)); }
    }
    if let Ok(c)=csscolorparser::parse(t) {
        if t.to_lowercase()=="transparent" { return None; }
        return Some(Color::from_css(c));
    }
    None
}

// Conversion helpers for output formats
fn format_color(c: &Color, fmt: &str) -> String {
    let srgb = c.to_srgb();
    let alpha = c.alpha;
    let has_alpha = alpha < 0.9999;
    match fmt {
        "hex" => {
            if has_alpha { format!("#{:02x}{:02x}{:02x}{:02x}", c.r,c.g,c.b,(alpha*255.0).round() as u8) }
            else { format!("#{:02x}{:02x}{:02x}", c.r,c.g,c.b) }
        },
        "rgb" => {
            if has_alpha { format!("rgba({}, {}, {}, {})", c.r,c.g,c.b, format_alpha(alpha)) }
            else { format!("rgb({}, {}, {})", c.r,c.g,c.b) }
        },
        "rgb-float" => {
            if has_alpha { format!("rgba({:.3}, {:.3}, {:.3}, {})", c.r as f32/255.0, c.g as f32/255.0, c.b as f32/255.0, format_alpha(alpha)) }
            else { format!("rgb({:.3}, {:.3}, {:.3})", c.r as f32/255.0, c.g as f32/255.0, c.b as f32/255.0) }
        },
        "rgb-r" => format!("{}", c.r),
        "rgb-g" => format!("{}", c.g),
        "rgb-b" => format!("{}", c.b),
        "hsl" => {
            let hsl: PalHsl = srgb.into_color();
            let h = hsl.hue.into_positive_degrees();
            let s = hsl.saturation*100.0;
            let l = hsl.lightness*100.0;
            if has_alpha { format!("hsla({:.0}, {:.1}%, {:.1}%, {})", h, s, l, format_alpha(alpha)) }
            else { format!("hsl({:.0}, {:.1}%, {:.1}%)", h, s, l) }
        },
        "hsl-hue" => { let hsl: PalHsl = srgb.into_color(); format!("{}", hsl.hue.into_positive_degrees().round() as i32) },
        "hsl-saturation" => { let hsl: PalHsl = srgb.into_color(); format!("{:.4}", hsl.saturation) },
        "hsl-lightness" => { let hsl: PalHsl = srgb.into_color(); format!("{:.4}", hsl.lightness) },
        "hsv" => {
            let hsv: PalHsv = srgb.into_color();
            let h = hsv.hue.into_positive_degrees();
            let s = hsv.saturation*100.0;
            let v = hsv.value*100.0;
            if has_alpha { format!("hsva({:.0}, {:.1}%, {:.1}%, {})", h, s, v, format_alpha(alpha)) }
            else { format!("hsv({:.0}, {:.1}%, {:.1}%)", h, s, v) }
        },
        "hsv-hue" => { let hsv: PalHsv = srgb.into_color(); format!("{}", hsv.hue.into_positive_degrees().round() as i32) },
        "hsv-saturation" => { let hsv: PalHsv = srgb.into_color(); format!("{:.4}", hsv.saturation) },
        "hsv-value" => { let hsv: PalHsv = srgb.into_color(); format!("{:.4}", hsv.value) },
        "lab" => {
            let lab: PalLab = srgb.into_color();
            if has_alpha { format!("Lab({:.0}, {:.0}, {:.0}, {})", lab.l.round(), lab.a.round(), lab.b.round(), format_alpha(alpha)) }
            else { format!("Lab({:.0}, {:.0}, {:.0})", lab.l.round(), lab.a.round(), lab.b.round()) }
        },
        "lab-a" => { let lab: PalLab = srgb.into_color(); format!("{:.2}", lab.a) },
        "lab-b" => { let lab: PalLab = srgb.into_color(); format!("{:.2}", lab.b) },
        "lch" => {
            let lch: PalLch = srgb.into_color();
            if has_alpha { format!("LCh({:.0}, {:.0}, {:.0}, {})", lch.l.round(), lch.chroma.round(), lch.hue.into_positive_degrees().round(), format_alpha(alpha)) }
            else { format!("LCh({:.0}, {:.0}, {:.0})", lch.l.round(), lch.chroma.round(), lch.hue.into_positive_degrees().round()) }
        },
        "lch-lightness" => { let lch: PalLch = srgb.into_color(); format!("{:.2}", lch.l) },
        "lch-chroma" => { let lch: PalLch = srgb.into_color(); format!("{:.2}", lch.chroma) },
        "lch-hue" => { let lch: PalLch = srgb.into_color(); format!("{:.2}", lch.hue.into_positive_degrees()) },
        "oklab" => {
            let oklab: PalOklab = srgb.into_color();
            if has_alpha { format!("OkLab({:.4}, {:.4}, {:.4}, {})", oklab.l, oklab.a, oklab.b, format_alpha(alpha)) }
            else { format!("OkLab({:.4}, {:.4}, {:.4})", oklab.l, oklab.a, oklab.b) }
        },
        "oklab-l" => { let oklab: PalOklab = srgb.into_color(); format!("{:.4}", oklab.l) },
        "oklab-a" => { let oklab: PalOklab = srgb.into_color(); format!("{:.4}", oklab.a) },
        "oklab-b" => { let oklab: PalOklab = srgb.into_color(); format!("{:.4}", oklab.b) },
        "oklch" => {
            let oklch: PalOklch = srgb.into_color();
            if has_alpha { format!("OkLCh({:.4}, {:.4}, {:.4}, {})", oklch.l, oklch.chroma, oklch.hue.into_positive_degrees(), format_alpha(alpha)) }
            else { format!("OkLCh({:.4}, {:.4}, {:.4})", oklch.l, oklch.chroma, oklch.hue.into_positive_degrees()) }
        },
        "oklch-lightness" => { let oklch: PalOklch = srgb.into_color(); format!("{:.4}", oklch.l) },
        "oklch-chroma" => { let oklch: PalOklch = srgb.into_color(); format!("{:.4}", oklch.chroma) },
        "oklch-hue" => { let oklch: PalOklch = srgb.into_color(); format!("{:.4}", oklch.hue.into_positive_degrees()) },
        "luminance" => {
            let r=c.r as f32/255.0; let g=c.g as f32/255.0; let b=c.b as f32/255.0;
            let rl=srgb_to_linear(r); let gl=srgb_to_linear(g); let bl=srgb_to_linear(b);
            let lum=0.2126*rl+0.7152*gl+0.0722*bl;
            format!("{:.3}", lum)
        },
        "brightness" => {
            let r=c.r as f32/255.0; let g=c.g as f32/255.0; let b=c.b as f32/255.0;
            let bright=0.299*r+0.587*g+0.114*b;
            format!("{:.3}", bright)
        },
        "cmyk" => {
            let r=c.r as f32/255.0; let g=c.g as f32/255.0; let b=c.b as f32/255.0;
            let k=1.0 - r.max(g).max(b);
            if k>=0.9999 {
                format!("cmyk(0, 0, 0, 100)")
            } else {
                let c_ = (1.0 - r - k)/(1.0 - k);
                let m = (1.0 - g - k)/(1.0 - k);
                let y = (1.0 - b - k)/(1.0 - k);
                format!("cmyk({:.0}, {:.0}, {:.0}, {:.0})", c_*100.0, m*100.0, y*100.0, k*100.0)
            }
        },
        "name" => {
            // find closest named color by minimal CIE76 distance (Lab Euclidean)
            let lab: PalLab = srgb.into_color();
            let mut best: Option<(String, f32)> = None;
            for (name, hex) in NAMED_COLORS.iter() {
                if let Some(ncol) = parse_color(hex) {
                    let nlab: PalLab = ncol.to_srgb().into_color();
                    let d = (lab.l - nlab.l).powi(2) + (lab.a - nlab.a).powi(2) + (lab.b - nlab.b).powi(2);
                    if best.is_none() || d < best.as_ref().unwrap().1 {
                        best = Some((name.to_string(), d));
                    }
                }
            }
            best.unwrap().0.clone()
        },
        "ansi-8bit" => format!("\x1b[38;5;{}m", ansi_8bit_value(c)),
        "ansi-24bit" => format!("\x1b[38;2;{};{};{}m", c.r, c.g, c.b),
        "ansi-8bit-value" => format!("{}", ansi_8bit_value(c)),
        "ansi-8bit-escapecode" => format!("\x1b[38;5;{}m", ansi_8bit_value(c)),
        "ansi-24bit-escapecode" => format!("\x1b[38;2;{};{};{}m", c.r,c.g,c.b),
        _ => format!("unknown format"),
    }
}

fn format_alpha(a: f32) -> String {
    // pastel seems to use 0.5 not 0.500 etc? We'll mimic: if alpha is fraction, print with 1 decimal? Actually for hsla they use 0.5
    // For our usage, we can just format with default maybe "0.5"
    // Remove trailing zeros?
    let s = format!("{:.2}", a);
    // But for test hsla they gave "0.5" not "0.50"
    // We'll trim
    let trimmed = s.trim_end_matches('0').trim_end_matches('.');
    trimmed.to_string()
}
fn srgb_to_linear(c: f32) -> f32 {
    if c <= 0.04045 { c/12.92 } else { ((c+0.055)/1.055).powf(2.4) }
}
