fn parse_color(s: &str) -> Option<Color> {
    let t = s.trim();
    if t.is_empty() { return None; }
    if t.to_lowercase()=="transparent" { return None; }
    if t.starts_with("gray(") && t.ends_with(')') {
        let inner = &t[5..t.len()-1].trim();
        let v = if inner.ends_with('%') {
            let num = inner.trim_end_matches('%').trim().parse::<f64>().ok()?;
            (num/100.0).clamp(0.0,1.0)
        } else {
            let num = inner.parse::<f64>().ok()?;
            if num > 1.0 { 1.0 } else { num.clamp(0.0,1.0) }
        };
        let byte = (v*255.0).round() as u8;
        return Some(Color::new(byte,byte,byte,1.0));
    }
    if let Some(open) = t.find('(') {
        if let Some(_) = t.rfind(')') {
            let fname = t[..open].trim();
            if fname.chars().any(|c| c.is_alphabetic()) && fname != fname.to_lowercase() {
                return None;
            }
        }
    }
    let try_palette = || -> Option<Color> {
        let open = t.find('(')?;
        let close = t.rfind(')')?;
        let fname = t[..open].trim();
        if fname != fname.to_lowercase() { return None; }
        let inner = t[open+1..close].trim();
        let normalized = inner.replace(',', " ");
        let parts: Vec<&str> = normalized.split_whitespace().filter(|s| !s.is_empty()).collect();
        match fname {
