        "ansi-24bit-escapecode" => format!("\x1b[38;2;{};{};{}m", c.r,c.g,c.b),
        _ => format!("unknown"),
    }
}

fn parse_args_collect_colors(args: &[String], start_idx: usize) -> (Vec<Color>, Vec<String>) {
    // Parses colors from args[start_idx..] and stdin if needed
    // Returns colors and errors? We'll just handle.
    // This is simplified.
    let mut colors = Vec::new();
    let mut errors = Vec::new();
    let mut iter = args[start_idx..].iter().peekable();
    while let Some(arg) = iter.next() {
        if arg=="-" {
            // read one color from stdin
            let stdin = io::stdin();
            let mut line = String::new();
            // read first non-empty line? Actually pastel reads one color from stdin for "-"
            // We'll read one line from stdin via BufRead
            let mut handle = stdin.lock();
            if handle.read_line(&mut line).unwrap_or(0) > 0 {
                let line = line.trim();
                if let Some(col) = parse_color(line) {
                    colors.push(col);
                } else {
                    errors.push(format!("[pastel error]: Could not parse color '{}'", line));
                }
            }
        } else if arg=="pick" {
            // external picker not available
            errors.push("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.".to_string());
        } else {
            if let Some(col) = parse_color(arg) {
                colors.push(col);
            } else {
                errors.push(format!("[pastel error]: Could not parse color '{}'", arg));
            }
        }
    }
    (colors, errors)
}

fn read_colors_from_stdin_if_no_args(provided: &[Color]) -> (Vec<Color>, Vec<String>) {
    if !provided.is_empty() {
        return (provided.to_vec(), Vec::new());
    }
    // read all lines from stdin
    let mut colors = Vec::new();
    let mut errors = Vec::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        if let Ok(line) = line {
            let t = line.trim();
            if t.is_empty() {
                errors.push("[pastel error]: Could not parse color ''".to_string());
                continue;
            }
            if let Some(col) = parse_color(t) {
                colors.push(col);
            } else {
                errors.push(format!("[pastel error]: Could not parse color '{}'", t));
            }
        }
    }
    (colors, errors)
}

