fn parse_color_mode(s: &str) -> Option<ColorMode> {
    match s.to_lowercase().as_str() {
        "auto" => Some(ColorMode::Auto),
        "off" => Some(ColorMode::Off),
        "8bit" => Some(ColorMode::Ansi8bit),
        "24bit" => Some(ColorMode::Ansi24bit),
        _ => None,
    }
}

fn resolve_color_mode(mode: ColorMode) -> ColorMode {
    match mode {
        ColorMode::Auto => {
            if env::var("NO_COLOR").is_ok() {
                return ColorMode::Off;
            }
            if let Ok(val) = env::var("PASTEL_COLOR_MODE") {
                if let Some(m) = parse_color_mode(&val) { return m; }
            }
            if let Ok(val) = env::var("FORCE_COLOR") { if !val.is_empty() { return ColorMode::Ansi24bit; } }
            // check if stdout is terminal and COLORTERM
            let is_tty = io::stdout().is_terminal();
            if !is_tty {
                return ColorMode::Off;
            }
            if let Ok(ct) = env::var("COLORTERM") {
                let ct = ct.to_lowercase();
                if ct == "truecolor" || ct == "24bit" {
                    return ColorMode::Ansi24bit;
                }
            }
            // fallback to 8bit with warning later? For now return 8bit if tty but no COLORTERM
            // Pastel warns and falls back to 8bit, but we will just return 8bit
            ColorMode::Ansi8bit
        },
        other => other,
    }
}

