fn get_colors_from_args(args: &[String], start: usize) -> (Vec<Color>, Vec<String>, bool) {
    let mut colors = Vec::new();
    let mut errors = Vec::new();
    let mut had_dash = false;
    let mut had_pick = false;
    for arg in &args[start..] {
        if arg == "-" {
            had_dash = true;
            // read one color from stdin
            let mut line = String::new();
            let stdin = io::stdin();
            let mut handle = stdin.lock();
            if handle.read_line(&mut line).unwrap_or(0) > 0 {
                let line = line.trim();
                if let Some(c) = parse_color(line) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", line)); }
            }
        } else if arg == "pick" {
            had_pick = true;
            errors.push("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.".to_string());
        } else {
            if let Some(c) = parse_color(arg) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", arg)); }
        }
    }
    (colors, errors, had_dash || had_pick)
}

fn read_stdin_colors() -> (Vec<Color>, Vec<String>) {
    let mut colors = Vec::new();
    let mut errors = Vec::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        if let Ok(line) = line {
            let t = line.trim();
            if t.is_empty() {
                errors.push("[pastel error]: Could not parse color ''".to_string());
                continue;
            }
            if let Some(c) = parse_color(t) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", t)); }
        }
    }
    (colors, errors)
}

