            else { eprintln!("error: a value is required for '--sort <sort-order>' but none was supplied"); std::process::exit(2); }
        } else if args[i].starts_with("--sort=") {
            sort = Box::leak(args[i].splitn(2,'=').nth(1).unwrap().to_string().into_boxed_str());
        } else if args[i]=="--help" || args[i]=="-h" {
            print_help_for("list");
            std::process::exit(0);
        } else {
            eprintln!("error: unexpected argument '{}' found", args[i]);
            eprintln!("\nUsage: {} list [OPTIONS]", env::args().next().unwrap());
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        i+=1;
    }
    let valid = ["brightness","luminance","hue","chroma","random"];
    if !valid.contains(&sort) {
        eprintln!("error: invalid value '{}' for '--sort <sort-order>'", sort);
        eprintln!("  [possible values: brightness, luminance, hue, chroma, random]");
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    let mut names: Vec<String> = NAMED_COLORS.iter().map(|(n,_)| n.to_string()).collect();
    // Sort logic: need to compute for each name its color and sort by property.
    // For hue, use hsl hue, for brightness use brightness, luminance use luminance, chroma use lch chroma.
    // We'll compute.
    let mut rng = rand::thread_rng();
    if sort=="random" {
        names.shuffle(&mut rng);
    } else {
        names.sort_by(|a,b| {
            let ca = parse_color(&NAMED_COLORS.iter().find(|(n,_)| n==a).unwrap().1).unwrap();
            let cb = parse_color(&NAMED_COLORS.iter().find(|(n,_)| n==b).unwrap().1).unwrap();
            let va = match sort {
                "brightness" => { let r=ca.r as f32/255.0; let g=ca.g as f32/255.0; let b=ca.b as f32/255.0; 0.299*r+0.587*g+0.114*b },
                "luminance" => { let r=ca.r as f32/255.0; let g=ca.g as f32/255.0; let b=ca.b as f32/255.0; let rl=srgb_to_linear(r); let gl=srgb_to_linear(g); let bl=srgb_to_linear(b); 0.2126*rl+0.7152*gl+0.0722*bl },
                "hue" => { let hsl: PalHsl = ca.to_srgb().into_color(); hsl.hue.into_positive_degrees() },
                "chroma" => { let lch: PalLch = ca.to_srgb().into_color(); lch.chroma },
                _ => 0.0,
            };
            let vb = match sort {
                "brightness" => { let r=cb.r as f32/255.0; let g=cb.g as f32/255.0; let b=cb.b as f32/255.0; 0.299*r+0.587*g+0.114*b },
                "luminance" => { let r=cb.r as f32/255.0; let g=cb.g as f32/255.0; let b=cb.b as f32/255.0; let rl=srgb_to_linear(r); let gl=srgb_to_linear(g); let bl=srgb_to_linear(b); 0.2126*rl+0.7152*gl+0.0722*bl },
                "hue" => { let hsl: PalHsl = cb.to_srgb().into_color(); hsl.hue.into_positive_degrees() },
                "chroma" => { let lch: PalLch = cb.to_srgb().into_color(); lch.chroma },
                _ => 0.0,
            };
            va.partial_cmp(&vb).unwrap()
        });
    }
    let is_tty = io::stdout().is_terminal();
    let resolved = match mode { ColorMode::Auto => resolve_color_mode(mode), _ => mode };
    let should_colorize = is_tty && resolved != ColorMode::Off;
    // Actually pastel's list when piped (not tty) gives no color even if forced 24bit (we saw list 24bit pipe gave no ansi). So for list, colorize only if tty and not Off.
    let should_colorize_list = is_tty && resolved != ColorMode::Off;
    for name in names {
        if should_colorize_list {
            // find color for name
            let hex = NAMED_COLORS.iter().find(|(n,_)| n==&name).unwrap().1;
            let col = parse_color(hex).unwrap();
            let fg = textcolor_for_bg(&col);
            let output = match resolved {
                ColorMode::Ansi8bit => format!("\x1b[38;5;{};48;5;{}m {:<25}\x1b[0m", ansi_8bit_value(&fg), ansi_8bit_value(&col), name),
                ColorMode::Ansi24bit => format!("\x1b[38;2;{};{};{};48;2;{};{};{}m {:<25}\x1b[0m", fg.r,fg.g,fg.b, col.r,col.g,col.b, name),
                _ => name.clone(),
            };
            println!("{}", output);
        } else {
            println!("{}", name);
        }
    }
}

