            let t = line.trim();
            if t.is_empty() { errors.push("[pastel error]: Could not parse color ''".to_string()); continue; }
            if let Some(c)=parse_color(t) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", t)); }
        }
    }
    (colors, errors)
}
