fn parse_color_mode(s: &str) -> Option<ColorMode> {
    match s.to_lowercase().as_str() {
        "auto" => Some(ColorMode::Auto),
        "off" => Some(ColorMode::Off),
        "8bit" => Some(ColorMode::Ansi8bit),
        "24bit" => Some(ColorMode::Ansi24bit),
        _ => None,
    }
}
fn resolve_color_mode(mode: ColorMode) -> ColorMode {
    match mode {
        ColorMode::Auto => {
            if std::env::var("NO_COLOR").is_ok() { return ColorMode::Off; }
            if let Ok(val) = std::env::var("PASTEL_COLOR_MODE") { if let Some(m) = parse_color_mode(&val) { return m; } }
            if let Ok(val) = std::env::var("FORCE_COLOR") { if !val.is_empty() { return ColorMode::Ansi24bit; } }
            let is_tty = std::io::stdout().is_terminal();
            if !is_tty { return ColorMode::Off; }
            if let Ok(ct) = std::env::var("COLORTERM") { let ct = ct.to_lowercase(); if ct == "truecolor" || ct == "24bit" { return ColorMode::Ansi24bit; } }
            ColorMode::Ansi8bit
        },
        other => other,
    }
}
fn print_warning_if_needed(mode: ColorMode, _resolved: ColorMode) {
    if mode == ColorMode::Auto {
        if let Ok(ct) = std::env::var("COLORTERM") { let ct = ct.to_lowercase(); if ct == "truecolor" || ct == "24bit" { return; } }
        if let Ok(pm) = std::env::var("PASTEL_COLOR_MODE") { if parse_color_mode(&pm).is_some() { return; } }
        if std::env::var("NO_COLOR").is_ok() { return; }
        if std::io::stdout().is_terminal() {
            eprintln!("\x1b[38;5;226m[pastel warning]\x1b[0m: Your terminal emulator does not appear to support 24-bit colors (this means that the COLORTERM environment variable is not set to 'truecolor' or '24bit'). pastel will fall back to 8-bit colors, but you will only be able to see rough approximations of the real colors.\n");
            eprintln!("To fix this, follow these steps:");
            eprintln!("  1. Run 'pastel colorcheck' to test if your terminal");
            eprintln!("     emulator does support 24-bit colors. If this is the");
            eprintln!("     case, set 'PASTEL_COLOR_MODE=24bit' to force 24-bit");
            eprintln!("     mode and to remove this warning. Alternatively, make");
            eprintln!("     sure that COLORTERM is properly set by your terminal");
            eprintln!("     emulator.");
            eprintln!("  2. If your terminal emulator does not support 24-bit");
            eprintln!("     colors, set 'PASTEL_COLOR_MODE=8bit' to remove this");
            eprintln!("     warning or try a different terminal emulator.");
            eprintln!();
            eprintln!("For more information, see https://gist.github.com/XVilka/8346728");
            eprintln!();
        }
    }
}
fn collect_colors(args: &[String], start: usize) -> (Vec<Color>, Vec<String>) {
    let mut colors = Vec::new(); let mut errors = Vec::new();
    for arg in &args[start..] {
        if arg=="-" {
            let mut line = String::new();
            let stdin = std::io::stdin();
            let mut handle = stdin.lock();
            if handle.read_line(&mut line).unwrap_or(0) > 0 {
                let line = line.trim();
                if line.is_empty() { errors.push("[pastel error]: Could not parse color ''".to_string()); }
                else if let Some(c)=parse_color(line) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", line)); }
            }
        } else if arg=="pick" {
            errors.push("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.".to_string());
        } else {
            if let Some(c)=parse_color(arg) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", arg)); }
        }
    }
    (colors, errors)
}
fn read_stdin_colors() -> (Vec<Color>, Vec<String>) {
    let mut colors = Vec::new(); let mut errors = Vec::new();
    let stdin = std::io::stdin();
    for line in stdin.lock().lines() {
        if let Ok(line)=line {
            let t = line.trim();
            if t.is_empty() { errors.push("[pastel error]: Could not parse color ''".to_string()); continue; }
            if let Some(c)=parse_color(t) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", t)); }
        }
    }
    (colors, errors)
}
fn textcolor_for_bg(c: &Color) -> Color {
    let lum = 0.2126*srgb_to_linear(c.r as f32/255.0) + 0.7152*srgb_to_linear(c.g as f32/255.0) + 0.0722*srgb_to_linear(c.b as f32/255.0);
    if lum > 0.179 { Color::new(0,0,0,1.0) } else { Color::new(255,255,255,1.0) }
}
fn colorize_format_output(text: &str, c: &Color, mode: ColorMode) -> String {
    match mode {
        ColorMode::Off => text.to_string(),
        ColorMode::Ansi8bit => {
            let fg = textcolor_for_bg(c);
            let fg_idx = ansi_8bit_value(&fg);
            let bg_idx = ansi_8bit_value(c);
            format!("\x1b[38;5;{};48;5;{}m{}\x1b[0m", fg_idx, bg_idx, text)
        },
        ColorMode::Ansi24bit => {
            let fg = textcolor_for_bg(c);
            format!("\x1b[38;2;{};{};{};48;2;{};{};{}m{}\x1b[0m", fg.r, fg.g, fg.b, c.r, c.g, c.b, text)
        },
        ColorMode::Auto => text.to_string(),
    }
}
