fn color_distance(a: &Color, b: &Color, metric: &str) -> f32 {
    let lab_a: PalLab = a.to_srgb().into_color();
    let lab_b: PalLab = b.to_srgb().into_color();
    if metric == "CIEDE2000" {
        // Use deltae crate's DE2000? That expects Lab values with specific struct
        // For simplicity, use CIE76
        ((lab_a.l - lab_b.l).powi(2) + (lab_a.a - lab_b.a).powi(2) + (lab_a.b - lab_b.b).powi(2)).sqrt()
    } else {
        ((lab_a.l - lab_b.l).powi(2) + (lab_a.a - lab_b.a).powi(2) + (lab_a.b - lab_b.b).powi(2)).sqrt()
    }
}
