                let hue: f32 = rng.gen_range(0.0..360.0);
                let sat: f32 = rng.gen_range(0.0..1.0);
                // pastel vivid: limited saturation/lightness? We'll just gen vivid as random hue, sat 0.4..0.8, light 0.4..0.6
                let sat = rng.gen_range(0.4..0.8);
                let light = rng.gen_range(0.3..0.7);
                let hsl = PalHsl::new(hue, sat, light);
                let srgb: Srgb = hsl.into_color();
                Color::from_srgb(srgb, 1.0)
            },
            "rgb" => {
                let r: u8 = rng.gen();
                let g: u8 = rng.gen();
                let b: u8 = rng.gen();
                Color::new(r,g,b,1.0)
            },
            "gray" => {
                let l: f32 = rng.gen_range(0.0..1.0);
                let byte = (l*255.0).round() as u8;
                Color::new(byte,byte,byte,1.0)
            },
            "lch_hue" => {
                let hue: f32 = rng.gen_range(0.0..360.0);
                // fixed lightness 70, chroma 30? We'll approximate
                let lch = PalLch::new(70.0, 30.0, hue);
                let srgb: Srgb = lch.into_color();
                let srgb = srgb.clamp();
                Color::from_srgb(srgb, 1.0)
            },
            _ => unreachable!(),
        };
        colors.push(c);
    }
    let is_tty = std::io::stdout().is_terminal();
    let resolved = match mode { ColorMode::Auto => resolve_color_mode(mode), _ => mode };
    if is_tty {
        for col in colors { print_color_box(&col, resolved); }
    } else {
        for col in colors { println!("{}", format_default(&col)); }
    }
}
