fn generate_gradient(colors: &[Color], n: usize, cs: &str) -> Vec<Color> {
    if n==0 { return Vec::new(); }
    if colors.len()==1 { return vec![colors[0]; n]; }
    let mut out = Vec::new();
    let segments = colors.len() - 1;
    for i in 0..n {
        let t_global = if n==1 { 0.0 } else { i as f32 / (n as f32 - 1.0) };
        let seg_f = t_global * segments as f32;
        let seg = (seg_f.floor() as usize).min(segments-1);
        let t_local = seg_f - seg as f32;
        let c1 = colors[seg];
        let c2 = colors[seg+1];
        let col = interpolate(c1, c2, t_local, cs);
        out.push(col);
    }
    out
}
fn interpolate(a: Color, b: Color, t: f32, cs: &str) -> Color {
    match cs {
        "Lab" => {
            let lab_a: PalLab = a.to_srgb().into_color();
            let lab_b: PalLab = b.to_srgb().into_color();
            let lab = lab_a.mix(lab_b, t);
            let srgb: Srgb = lab.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        "LCh" => {
            let lch_a: PalLch = a.to_srgb().into_color();
            let lch_b: PalLch = b.to_srgb().into_color();
            // need to handle hue interpolation shortest path
            let mut h_a = lch_a.hue.into_positive_degrees();
            let mut h_b = lch_b.hue.into_positive_degrees();
            let mut dh = h_b - h_a;
            if dh > 180.0 { dh -= 360.0; } else if dh < -180.0 { dh += 360.0; }
            let h = (h_a + t*dh + 360.0) % 360.0;
            let lch = PalLch::new(lch_a.l + t*(lch_b.l - lch_a.l), lch_a.chroma + t*(lch_b.chroma - lch_a.chroma), h);
            let srgb: Srgb = lch.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        "RGB" => {
            let srgb_a = a.to_srgb();
            let srgb_b = b.to_srgb();
            let r = srgb_a.red + t*(srgb_b.red - srgb_a.red);
            let g = srgb_a.green + t*(srgb_b.green - srgb_a.green);
            let b_ = srgb_a.blue + t*(srgb_b.blue - srgb_a.blue);
            Color::from_srgb(Srgb::new(r,g,b_), a.alpha*(1.0-t)+b.alpha*t)
        },
        "HSL" => {
            let hsl_a: PalHsl = a.to_srgb().into_color();
            let hsl_b: PalHsl = b.to_srgb().into_color();
            let mut h_a = hsl_a.hue.into_positive_degrees();
            let mut h_b = hsl_b.hue.into_positive_degrees();
            let mut dh = h_b - h_a;
            if dh > 180.0 { dh -= 360.0; } else if dh < -180.0 { dh += 360.0; }
            let h = (h_a + t*dh + 360.0) % 360.0;
            let hsl = PalHsl::new(h, hsl_a.saturation + t*(hsl_b.saturation - hsl_a.saturation), hsl_a.lightness + t*(hsl_b.lightness - hsl_a.lightness));
            let srgb: Srgb = hsl.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        "OkLab" => {
            let oklab_a: PalOklab = a.to_srgb().into_color();
            let oklab_b: PalOklab = b.to_srgb().into_color();
            let oklab = oklab_a.mix(oklab_b, t);
            let srgb: Srgb = oklab.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        _ => a,
    }
}
fn handle_mix(args: &[String], mode: ColorMode) {
