fn handle_to_gray(args: &[String], mode: ColorMode) {
    let (mut colors, mut errors) = collect_colors(args, 0);
    if colors.is_empty() && args.is_empty() {
        let (stdin_colors, stdin_errors) = read_stdin_colors();
        colors.extend(stdin_colors);
        errors.extend(stdin_errors);
    }
    for e in &errors { eprintln!("{}", e); }
    if !errors.is_empty() && colors.is_empty() { std::process::exit(1); }
    let is_tty = std::io::stdout().is_terminal();
    let resolved = match mode { ColorMode::Auto => resolve_color_mode(mode), _ => mode };
    for col in colors {
        // Desaturate preserving luminance: use luminance as lightness in gray?
        // Pastel's to-gray preserves luminance: they compute luminance and create gray with that luminance as light?
        // We can approximate: compute luminance and create gray with that luminance as HSL lightness? But hsl lightness not same as luminance.
        // Let's use luminance directly as gray value: gray = luminance*255
        let r = col.r as f32/255.0; let g = col.g as f32/255.0; let b = col.b as f32/255.0;
        let rl=srgb_to_linear(r); let gl=srgb_to_linear(g); let bl=srgb_to_linear(b);
        let lum=0.2126*rl+0.7152*gl+0.0722*bl;
        // Convert lum back to srgb gray: need linear to srgb
        let gray_linear = lum;
        let gray_srgb = if gray_linear <= 0.0031308 { gray_linear*12.92 } else { 1.055*gray_linear.powf(1.0/2.4)-0.055 };
        let byte = (gray_srgb*255.0).round().clamp(0.0,255.0) as u8;
        let new_col = Color::new(byte,byte,byte,col.alpha);
        if is_tty { print_color_box(&new_col, resolved); } else { println!("{}", format_default(&new_col)); }
    }
    if !errors.is_empty() { std::process::exit(1); }
}
