fn generate_gradient(colors: &[Color], n: usize, cs: &str) -> Vec<Color> {
    if n==0 { return Vec::new(); }
    if colors.len()==1 { return vec![colors[0]; n]; }
    let mut out = Vec::new();
    let segments = colors.len() - 1;
    for i in 0..n {
        let t_global = if n==1 { 0.0 } else { i as f32 / (n as f32 - 1.0) };
        let seg_f = t_global * segments as f32;
        let seg = (seg_f.floor() as usize).min(segments-1);
        let t_local = seg_f - seg as f32;
        let c1 = colors[seg];
        let c2 = colors[seg+1];
        let col = interpolate(c1, c2, t_local, cs);
        out.push(col);
    }
    out
}
fn interpolate(a: Color, b: Color, t: f32, cs: &str) -> Color {
    match cs {
        "Lab" => {
            let lab_a: PalLab = a.to_srgb().into_color();
            let lab_b: PalLab = b.to_srgb().into_color();
            let lab = lab_a.mix(lab_b, t);
            let srgb: Srgb = lab.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        "LCh" => {
            let lch_a: PalLch = a.to_srgb().into_color();
            let lch_b: PalLch = b.to_srgb().into_color();
            // need to handle hue interpolation shortest path
            let mut h_a = lch_a.hue.into_positive_degrees();
            let mut h_b = lch_b.hue.into_positive_degrees();
            let mut dh = h_b - h_a;
            if dh > 180.0 { dh -= 360.0; } else if dh < -180.0 { dh += 360.0; }
            let h = (h_a + t*dh + 360.0) % 360.0;
            let lch = PalLch::new(lch_a.l + t*(lch_b.l - lch_a.l), lch_a.chroma + t*(lch_b.chroma - lch_a.chroma), h);
            let srgb: Srgb = lch.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        "RGB" => {
            let srgb_a = a.to_srgb();
            let srgb_b = b.to_srgb();
            let r = srgb_a.red + t*(srgb_b.red - srgb_a.red);
            let g = srgb_a.green + t*(srgb_b.green - srgb_a.green);
            let b_ = srgb_a.blue + t*(srgb_b.blue - srgb_a.blue);
            Color::from_srgb(Srgb::new(r,g,b_), a.alpha*(1.0-t)+b.alpha*t)
        },
        "HSL" => {
            let hsl_a: PalHsl = a.to_srgb().into_color();
            let hsl_b: PalHsl = b.to_srgb().into_color();
            let mut h_a = hsl_a.hue.into_positive_degrees();
            let mut h_b = hsl_b.hue.into_positive_degrees();
            let mut dh = h_b - h_a;
            if dh > 180.0 { dh -= 360.0; } else if dh < -180.0 { dh += 360.0; }
            let h = (h_a + t*dh + 360.0) % 360.0;
            let hsl = PalHsl::new(h, hsl_a.saturation + t*(hsl_b.saturation - hsl_a.saturation), hsl_a.lightness + t*(hsl_b.lightness - hsl_a.lightness));
            let srgb: Srgb = hsl.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        "OkLab" => {
            let oklab_a: PalOklab = a.to_srgb().into_color();
            let oklab_b: PalOklab = b.to_srgb().into_color();
            let oklab = oklab_a.mix(oklab_b, t);
            let srgb: Srgb = oklab.into_color();
            Color::from_srgb(srgb, a.alpha*(1.0-t)+b.alpha*t)
        },
        _ => a,
    }
}
fn handle_mix(args: &[String], mode: ColorMode) {
    let mut colorspace = "Lab";
    let mut fraction = 0.5f32;
    let mut color_strs: Vec<String> = Vec::new();
    let mut i=0;
    while i<args.len() {
        if args[i]=="-s" || args[i]=="--colorspace" {
            if i+1<args.len() { colorspace = Box::leak(args[i+1].clone().into_boxed_str()); i+=2; continue; }
            else { eprintln!("error: a value is required for '--colorspace <name>'"); std::process::exit(2); }
        } else if args[i].starts_with("--colorspace=") {
            colorspace = Box::leak(args[i].splitn(2,'=').nth(1).unwrap().to_string().into_boxed_str());
        } else if args[i]=="-f" || args[i]=="--fraction" {
            if i+1<args.len() { fraction = args[i+1].parse().unwrap_or_else(|_| { eprintln!("[pastel error]: Could not parse number '{}'", args[i+1]); std::process::exit(1); }); i+=2; continue; }
            else { eprintln!("error: a value is required for '--fraction <fraction>'"); std::process::exit(2); }
        } else if args[i].starts_with("--fraction=") {
            let v = args[i].splitn(2,'=').nth(1).unwrap();
            fraction = v.parse().unwrap_or_else(|_| { eprintln!("[pastel error]: Could not parse number '{}'", v); std::process::exit(1); });
        } else if args[i]=="--help" || args[i]=="-h" {
            println!("Create new colors by interpolating between two colors in the given colorspace.\n");
            println!("Example:");
            println!("  pastel mix --colorspace=RGB red blue\n");
            println!("Usage: {} mix [OPTIONS] <color> [color]...\n", std::env::args().next().unwrap());
            println!("Arguments:");
            println!("  <color>");
            println!("          The base color which will be mixed with the other colors\n");
            println!("  [color]...");
            std::process::exit(0);
        } else if args[i].starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", args[i]);
            std::process::exit(2);
        } else {
            color_strs.push(args[i].clone());
        }
        i+=1;
    }
    let valid_cs = ["Lab","LCh","RGB","HSL","OkLab"];
    if !valid_cs.contains(&colorspace) {
        eprintln!("error: invalid value '{}' for '--colorspace <name>'", colorspace);
        eprintln!("  [possible values: Lab, LCh, RGB, HSL, OkLab]");
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if color_strs.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <color>");
        eprintln!("\nUsage: {} mix <color> [color]...", std::env::args().next().unwrap());
        std::process::exit(2);
    }
    let base_str = color_strs[0].clone();
    let other_strs = &color_strs[1..];
    let base = if let Some(c)=parse_color(&base_str) { c } else { eprintln!("[pastel error]: Could not parse color '{}'", base_str); std::process::exit(1); };
    let mut others: Vec<Color> = Vec::new();
    let mut errors = Vec::new();
    for s in other_strs {
        if let Some(c)=parse_color(s) { others.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", s)); }
    }
    // If no others via args, try stdin
    if others.is_empty() && other_strs.is_empty() {
        let (stdin_colors, stdin_errors) = read_stdin_colors();
        others.extend(stdin_colors);
        errors.extend(stdin_errors);
    }
    for e in &errors { eprintln!("{}", e); }
    if !errors.is_empty() { std::process::exit(1); }
    if others.is_empty() {
        // No other colors to mix? Original pastel would just output nothing? Let's just exit
        return;
    }
    let is_tty = std::io::stdout().is_terminal();
    let resolved = match mode { ColorMode::Auto => resolve_color_mode(mode), _ => mode };
    for other in others {
        let mixed = interpolate(base, other, 1.0 - fraction, colorspace);
        // Note: pastel's mix fraction is how much to mix in from base? They say fraction 0.5 means equal. So interpolate with t = 1 - fraction? Let's test: mix red blue fraction 0.5 should be middle, which we do with t=0.5? But we use 1 - fraction for mixing base into other? Let's align: base = red, other = blue, fraction 0.5 => mix 50% base. That means result is halfway between base and other. So t is fraction of other? Actually interpolate(base, other, 1 - fraction) gives 50% when fraction 0.5. For fraction 0 (no base), result should be other (blue). Our interpolate(base, other, 1 - 0 =1) => other correct. For fraction 1 (all base), interpolate(...,0) => base correct. So we use t = 1 - fraction.
        if is_tty {
            print_color_box(&mixed, resolved);
        } else {
            println!("{}", format_default(&mixed));
        }
    }
}
