fn simulate_colorblind(c: &Color, typ: &str) -> Color {
    // Use simple matrices for protan/deuter/tritan as per pastel's likely implementation
    // We'll use the matrices from https://www.inf.ufrgs.br/~oliveira/pubs_files/CVD_Simulation/CVD_Simulation.html
    // Simplified.
    let r = c.r as f32/255.0; let g = c.g as f32/255.0; let b = c.b as f32/255.0;
    let (r2,g2,b2) = match typ {
        "prot" => {
            // protanopia matrix
            let r_ = 0.567*r + 0.433*g + 0.0*b;
            let g_ = 0.558*r + 0.442*g + 0.0*b;
            let b_ = 0.0*r + 0.242*g + 0.758*b;
            (r_,g_,b_)
        },
        "deuter" => {
            let r_ = 0.625*r + 0.375*g + 0.0*b;
            let g_ = 0.70*r + 0.30*g + 0.0*b;
            let b_ = 0.0*r + 0.30*g + 0.70*b;
            (r_,g_,b_)
        },
        "trit" => {
            let r_ = 0.95*r + 0.05*g + 0.0*b;
            let g_ = 0.0*r + 0.433*g + 0.567*b;
            let b_ = 0.0*r + 0.475*g + 0.525*b;
            (r_,g_,b_)
        },
        _ => (r,g,b),
    };
    Color::new((r2*255.0).round().clamp(0.0,255.0) as u8, (g2*255.0).round().clamp(0.0,255.0) as u8, (b2*255.0).round().clamp(0.0,255.0) as u8, c.alpha)
}
fn handle_set(args: &[String], mode: ColorMode) {
