fn handle_sort_by(args: &[String], mode: ColorMode) {
    let mut sort = "hue";
    let mut reverse = false;
    let mut unique = false;
    let mut color_strs: Vec<String> = Vec::new();
    let mut i=0;
    while i<args.len() {
        if args[i]=="-r" || args[i]=="--reverse" {
            reverse=true;
        } else if args[i]=="-u" || args[i]=="--unique" {
            unique=true;
        } else if args[i].starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", args[i]);
            std::process::exit(2);
        } else {
            // first non-flag could be sort-order if it's valid
            let valid = ["brightness","luminance","hue","chroma","random"];
            if valid.contains(&args[i].as_str()) && color_strs.is_empty() && i==0 {
                sort = Box::leak(args[i].clone().into_boxed_str());
            } else if valid.contains(&args[i].as_str()) && sort=="hue" && i==0 {
                sort = Box::leak(args[i].clone().into_boxed_str());
            } else {
                color_strs.push(args[i].clone());
            }
        }
        i+=1;
    }
    // If first arg was sort-order, we already consumed; but if color_strs first element is actually sort-order when we had no explicit? The above handles.
    // Simpler: if args len >=1 and valid contains args[0], treat as sort, else default hue and all args are colors
    // Re-parse correctly:
    let mut sort_order = "hue";
    let mut colors_start = 0;
    if !args.is_empty() {
        let first = &args[0];
        if ["brightness","luminance","hue","chroma","random"].contains(&first.as_str()) {
            sort_order = first;
            colors_start = 1;
            // need to re-extract flags after? But flags were already handled above with i loop that consumed all.
            // For simplicity, if first arg was sort, then color_strs already contains remaining colors (excluding flags). Our earlier loop already pushed colors including after sort? It pushed all non-flag args after handling sort? Actually we handled sort detection inside loop, so it's okay.
            // But we double counted. Let's just use color_strs as is and sort variable.
            sort_order = sort;
        } else {
            // Check if any flag handling messed? We'll just use color_strs as collected and sort as default
            // If sort was not set via flag, keep hue
        }
    }
    // Collect colors from color_strs and possibly stdin
    let mut colors: Vec<Color> = Vec::new();
    let mut errors = Vec::new();
    for s in &color_strs {
        if let Some(c)=parse_color(s) { colors.push(c); } else { errors.push(format!("[pastel error]: Could not parse color '{}'", s)); }
    }
    if colors.is_empty() && color_strs.is_empty() {
        let (stdin_colors, stdin_errors) = read_stdin_colors();
        colors.extend(stdin_colors);
        errors.extend(stdin_errors);
    }
    for e in &errors { eprintln!("{}", e); }
    if !errors.is_empty() && colors.is_empty() { std::process::exit(1); }
    // Unique
    if unique {
        let mut seen: Vec<(u8,u8,u8)> = Vec::new();
        let mut uniq: Vec<Color> = Vec::new();
        for c in colors {
            let key = (c.r,c.g,c.b);
            if !seen.contains(&key) {
                seen.push(key);
                uniq.push(c);
            }
        }
        colors = uniq;
    }
    // Sort
    match sort_order {
        "brightness" => colors.sort_by(|a,b| {
            let va = 0.299*(a.r as f32/255.0)+0.587*(a.g as f32/255.0)+0.114*(a.b as f32/255.0);
            let vb = 0.299*(b.r as f32/255.0)+0.587*(b.g as f32/255.0)+0.114*(b.b as f32/255.0);
            va.partial_cmp(&vb).unwrap()
        }),
        "luminance" => colors.sort_by(|a,b| {
            let va = 0.2126*srgb_to_linear(a.r as f32/255.0)+0.7152*srgb_to_linear(a.g as f32/255.0)+0.0722*srgb_to_linear(a.b as f32/255.0);
            let vb = 0.2126*srgb_to_linear(b.r as f32/255.0)+0.7152*srgb_to_linear(b.g as f32/255.0)+0.0722*srgb_to_linear(b.b as f32/255.0);
            va.partial_cmp(&vb).unwrap()
        }),
        "hue" => colors.sort_by(|a,b| {
            let ha: f32 = { let hsl: PalHsl = a.to_srgb().into_color(); hsl.hue.into_positive_degrees() };
            let hb: f32 = { let hsl: PalHsl = b.to_srgb().into_color(); hsl.hue.into_positive_degrees() };
            ha.partial_cmp(&hb).unwrap()
        }),
        "chroma" => colors.sort_by(|a,b| {
            let ca: f32 = { let lch: PalLch = a.to_srgb().into_color(); lch.chroma };
            let cb: f32 = { let lch: PalLch = b.to_srgb().into_color(); lch.chroma };
            ca.partial_cmp(&cb).unwrap()
        }),
        "random" => {
            let mut rng = rand::thread_rng();
            colors.shuffle(&mut rng);
        },
        _ => {},
    }
    if reverse { colors.reverse(); }
    let is_tty = std::io::stdout().is_terminal();
    let resolved = match mode { ColorMode::Auto => resolve_color_mode(mode), _ => mode };
    if is_tty {
        for col in colors { print_color_box(&col, resolved); }
    } else {
        for col in colors { println!("{}", format_default(&col)); }
    }
    if !errors.is_empty() { std::process::exit(1); }
}
fn handle_paint(args: &[String], mode: ColorMode) {
