    if args.len()==1 {
        print_help_top();
        std::process::exit(0);
    }
    let mut color_mode = ColorMode::Auto;
    let mut force_color = false;
    let mut subcommand_idx: Option<usize> = None;
    let mut color_picker: Option<String> = None;
    let mut i=1;
    while i<args.len() {
        let arg = &args[i];
        if arg=="--color-picker" {
            if i+1 < args.len() { color_picker = Some(args[i+1].clone()); i+=2; continue; }
            else { eprintln!("error: a value is required for '--color-picker <color-picker>' but none was supplied"); std::process::exit(2); }
        } else if arg.starts_with("--color-picker=") {
            color_picker = Some(arg.splitn(2,'=').nth(1).unwrap().to_string());
        } else if arg=="--color-mode" || arg=="-m" {
            if i+1 < args.len() {
                if let Some(m)=parse_color_mode(&args[i+1]) { color_mode = m; } else {
                    eprintln!("error: invalid value '{}' for '--color-mode <mode>'\n  [possible values: 24bit, 8bit, off, *auto*]", args[i+1]);
                    eprintln!("\nFor more information, try '--help'.");
                    std::process::exit(2);
                }
                i+=2; continue;
            } else { eprintln!("error: a value is required for '--color-mode <mode>'"); std::process::exit(2); }
        } else if arg.starts_with("--color-mode=") {
            let val = arg.splitn(2,'=').nth(1).unwrap();
            if let Some(m)=parse_color_mode(val) { color_mode = m; } else {
                eprintln!("error: invalid value '{}' for '--color-mode <mode>'\n  [possible values: 24bit, 8bit, off, *auto*]", val);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        } else if arg=="--force-color" || arg=="-f" {
            force_color = true;
            color_mode = ColorMode::Ansi24bit;
        } else if arg=="--help" || arg=="-h" {
            if subcommand_idx.is_none() {
                print_help_top();
                std::process::exit(0);
            }
        } else if arg=="--version" || arg=="-V" {
            print_version();
            std::process::exit(0);
        } else if arg=="help" {
            if i+1 < args.len() {
                let cmd = args[i+1].clone();
                print_help_for(&cmd);
                std::process::exit(0);
            } else {
                print_help_top();
                std::process::exit(0);
            }
        } else if arg.starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!("\nUsage: {} [OPTIONS] <COMMAND>", args[0]);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        } else {
            subcommand_idx = Some(i);
            break;
        }
        i+=1;
    }
    if subcommand_idx.is_none() {
        print_help_top();
        std::process::exit(0);
    }
    let idx = subcommand_idx.unwrap();
    let subcmd = args[idx].clone();
    let sub_args = &args[idx+1..];
    if sub_args.iter().any(|a| a=="--help" || a=="-h") {
        print_help_for(&subcmd);
        std::process::exit(0);
    }
    let resolved = resolve_color_mode(color_mode);
